// ==================== 1. 武器附魔 ====================
export const WEAPON_ABILITIES = [
  { id: "ally", name: "同盟", bonus: 1, cl: 5, type: "both", req: "", desc: "灵光：微弱变化系。同盟武器允许持用者将该武器的增强加值转移到某个同伴手持的武器上。持用者与其同伴之间必须要有效果线。在持用者的回合开始时，持用者能以自由动作选择如何分配武器上的增强加值。转移到同伴武器上的增强加值将在同盟武器持用者的下一个回合开始时，回归到同盟武器上。同盟武器转移过去的增强加值，不与同伴的武器上的增强加值叠加（如果有）。" },
  { id: "bane", name: "破敌", bonus: 1, cl: 8, type: "both", req: "", desc: "灵光：中等咒法系。破敌武器在攻击某一特定种类的生物时特别有效。在对抗此类生物时，它的增强加值比正常时多+2，并能造成2d6点额外伤害。" },
  { id: "benevolent", name: "助力", bonus: 1, cl: 5, type: "melee", req: "", desc: "灵光：微弱附魔系。当持用者使用援助他人动作来增加同伴的攻击加值时，他可以将慈善武器上的增强加值添加到协助同伴带来的攻击加值上。" },
  { id: "called", name: "呼回", bonus: 1, cl: 9, type: "both", req: "", desc: "灵光：中等咒法系。以一个不会引发借机攻击的迅捷动作，持用者可以将呼回武器传送回自己的手上，哪怕该武器在别人的手中。这个传送能力的最大范围为100尺，并且阻止传送能力的效果同样可以阻止呼回武器的传送。只有持有呼回武器至少24小时的人才能使呼回武器起作用。" },
  { id: "conductive", name: "传导", bonus: 1, cl: 8, type: "both", req: "", desc: "灵光：中等死灵系。传导武器被设计用来传导近战或远程接触攻击形式的类法术能力和超自然能力。当传导武器成功命中一个生物时，他可以花费2次特殊能力使用次数，通过武器将该特殊能力传导过去，使目标同时承受武器攻击和特殊能力攻击。一名角色每轮只可以使用该武器特殊能力一次，并且只有传导的能力和武器类型同属一类时才可生效。" },
  { id: "corrosive", name: "酸蚀", bonus: 1, cl: 10, type: "both", req: "", desc: "灵光：中等塑能系。一旦被下令启动，酸蚀武器便被酸包覆。强酸不会伤害持用者，其效果一直持续到持用者再次对武器下令。攻击成功时，酸蚀武器造成额外1d6点强酸伤害。" },
  { id: "countering", name: "反制", bonus: 1, cl: 5, type: "melee", req: "", desc: "灵光：微弱变化系。反制武器使得用者对抗卸武和破武战技的CMD+2（仅针对该武器）。在敌人的尝试失败后，该武器持用者可以立刻对敌人进行一次相同的战技尝试，并且不引发借机攻击。哪怕持用者的该次战技尝试失败了，他也无需丢弃该武器。反制能力只能附加在近战武器上。" },
  { id: "courageous", name: "英勇", bonus: 1, cl: 3, type: "melee", req: "", desc: "灵光：微弱附魔系。这项附魔只能附加在近战武器上。英勇武器鼓舞人心、激励起士气和信心。持用者对抗恐惧的豁免得到等同于该武器增强加值的士气加值。额外的，持有者从其它地方得到的对抗恐惧的士气加值，增加一半武器增强加值的数值（最小为1），两者效果的士气加值取高。" },
  { id: "cruel", name: "残忍", bonus: 1, cl: 5, type: "both", req: "", desc: "灵光：微弱死灵系。当使用残忍武器命中一个战栗、惊惧、恐慌中的生物，那个生物将恶心1轮。如果持用者用该武器命中一个昏迷目标或者击杀一个生物，他将得到5点临时HP，持续10分钟。" },
  { id: "cunning", name: "狡诈", bonus: 1, cl: 6, type: "both", req: "", desc: "灵光：中等预言系。这件武器允许它使用持用者的知识来从生物身上的伤口处发现弱点。当用该武器造成一次重击威胁时，持有者若在相关生物类型的知识上至少有5个级别，那么在重击确认投上得到+4加值，如果知识级别至少为15，则重击确认投上获得的加值变为+6。" },
  { id: "deadly", name: "致命", bonus: 1, cl: 5, type: "melee", req: "", desc: "灵光：微弱死灵系。这项附魔只能附加在通常造成非致命伤害的近战武器上。致命武器造成的所有伤害皆为正常伤害。以一个口令，持用者可以关闭致命特效，直到使用另一个口令启动。" },
  { id: "defending", name: "护体", bonus: 1, cl: 8, type: "melee", req: "", desc: "灵光：中等防护系。护体武器允许持用者把部分或全部的增强加值转换为AC，此加值可以和任何加值累计。每轮持用者开始进行动作前，他必须决定如何分配武器的增强加值。这项附魔只能附加在近战武器上。" },
  { id: "dispelling", name: "破法", bonus: 1, cl: 10, type: "both", req: "", desc: "灵光：强烈防护系。破法武器如同储法武器一般，不过只能储存“解除魔法”法术。解除魔法的施法者等级检定得到加值，数值等同于武器增强加值。" },
  { id: "flaming", name: "炽焰", bonus: 1, cl: 10, type: "both", req: "", desc: "灵光：中等塑能系。一旦被下令启动，炽焰武器便被火包覆。火焰不会伤害持用者。攻击成功时，炽焰武器造成额外1d6点火焰伤害。" },
  { id: "frost", name: "冻寒", bonus: 1, cl: 8, type: "both", req: "", desc: "灵光：中等塑能系。一旦被下令启动，冻寒武器便被寒冷的冰包覆。寒冰不会伤害持用者。攻击成功时，冻寒武器造成额外1d6点寒冷伤害。" },
  { id: "furious", name: "暴怒", bonus: 1, cl: 8, type: "melee", req: "", desc: "灵光：中等附魔系。这项附魔只能附加在近战武器上。当持用者狂暴或者受到‘狂暴术’影响，该武器的增强加值视为正常+2。如果持用者拥有狂暴时增加技能检定的狂暴之力，持用者的对应技能检定得到增强加值，加值等同于武器的增强加值。" },
  { id: "ghost_touch", name: "幽冥", bonus: 1, cl: 9, type: "both", req: "", desc: "灵光：中等咒法系。幽冥武器能正常伤害虚体生物，且无视其加值。本质上，幽冥武器是实体或虚体取决于哪种形式对持用者更有利。这项附魔只能附加在近战武器和弹药上。" },
  { id: "grayflame", name: "灰焰", bonus: 1, cl: 6, type: "melee", req: "", desc: "灵光：中等变化系。当持用者以迅捷动作将正/负能量引导进武器中，该武器的增强加值+1，并造成额外1d6点伤害。当引导正能量进入武器时，武器击穿DR时视为善良阵营武器和寒铁武器。这项附魔只能附加在近战武器上。" },
  { id: "grounding", name: "接地", bonus: 1, cl: 5, type: "melee", req: "", desc: "灵光：微弱变化系。这项附魔只能附加在近战武器上。当用接地武器攻击气系亚种生物时，额外造成1d6点伤害。在对抗气系和电击攻击时，接地武器持用者的豁免得到+2环境加值。武器本身免疫电击伤害。" },
  { id: "guardian", name: "守护", bonus: 1, cl: 8, type: "melee", req: "", desc: "灵光：中等防护系。这项附魔只能附加在近战武器上。守护武器允许持用者把部分或全部的增强加值转换为豁免加值，此加值可以和任何加值累计。如果武器同时具有（护体）和（守护）附魔，每1点增强加值必须单独选择转换为AC还是豁免。" },
  { id: "heartseeker", name: "觅心", bonus: 1, cl: 7, type: "melee", req: "", desc: "灵光：中等死灵系。这项附魔只能附加在近战武器上。觅心武器在攻击大多数活物时忽视隐蔽带来的失手率。这个能力对异性、泥怪、植物、异界生物、元素生物不起作用，对那些没有心脏的生物亦不起效。" },
  { id: "huntsman", name: "追猎", bonus: 1, cl: 7, type: "both", req: "", desc: "灵光：中等预言系。当该武器被持握于手，持用者在使用生存技能追踪被该武器击伤的目标时，野外求生技能检定得到增强加值。使用该武器可以对曾被持用者追踪的目标造成额外1d6点伤害。" },
  { id: "jurist", name: "法理", bonus: 1, cl: 4, type: "both", req: "", desc: "灵光：微弱变化系。一名审判者持用法理武器并使用他的【审判】职业能力时，他的察觉检定和CMD得到增强加值。这个加值在他使用【审判】的第一轮里为+1，然后每轮+1，最大值为+3，并且一直持续。" },
  { id: "keen", name: "锐锋", bonus: 1, cl: 10, type: "both", req: "slashing_piercing", desc: "灵光：中等变化系。这一特殊能力可以加倍武器的重击威胁范围。只有穿刺或挥砍型近战武器能具有此能力。锐锋效果不能和其他任何能扩展重击范围的效果叠加。" },
  { id: "ki_focus", name: "真气", bonus: 1, cl: 8, type: "melee", req: "", desc: "灵光：中等变化系。这项附魔只能附加在近战武器上。这种魔法武器引导持用者身体内的气，允许持用者通过该武器使出气来攻击，如同徒手使用气一般。这些攻击包括【斗气击】、【渗透劲】和“震慑拳”专长。" },
  { id: "limning", name: "妖火", bonus: 1, cl: 5, type: "both", req: "", desc: "灵光：微弱塑能系。当持有妖火武器时，一轮光晕在它周身环绕。当用该武器击中一个受到魔法隐蔽的生物时。武器勾画出该生物的轮廓，如同“妖火术”，持续1轮。" },
  { id: "lucky", name: "幸运", bonus: 1, cl: 8, type: "ranged", req: "firearm", desc: "灵光：中等变化系。这个特殊能力只能添加在单手火器或双手火器上。一件幸运火器有它自己的魔法勇毅池，有1点勇毅点，并在每天的开始恢复。持用者能随时从幸运武器中消耗1点勇毅点重掷一个原本会导致不发火的攻击检定。" },
  { id: "menacing", name: "威胁", bonus: 1, cl: 10, type: "melee", req: "", desc: "灵光：中等幻术系。这项附魔只能附加在近战武器上。当持用者临近一个被同伴夹击的敌人时，同伴得到的夹击攻击加值额外增加2。该武器持用者即使不是夹击的一员，也同样可以给予同伴该加值。" },
  { id: "merciful", name: "慈悯", bonus: 1, cl: 5, type: "both", req: "", desc: "灵光：微弱咒法系。慈悯武器能造成1d6点额外伤害，并且此时它造成的全部伤害都是非致命伤害。一旦收到持用者的命令，武器转为造成正常伤害，直到持用者再次下令。" },
  { id: "mighty_cleaving", name: "狂斩", bonus: 1, cl: 8, type: "melee", req: "", desc: "灵光：中等塑能系。这项附魔只能附加在近战武器上。狂斩武器允许持用者使用“顺势斩”专长，在第一次攻击命中时，攻击一个额外的敌人。这次额外攻击的目标必须临近第一个目标，并且在持用者的触及范围内。" },
  { id: "mimetic", name: "模仿", bonus: 1, cl: 5, type: "melee", req: "", desc: "灵光：微弱防护系。这项附魔只能附加在近战武器上。每当持用者用该武器对敌人造成伤害时，他得到10点能量抗力，持续1轮；该抗力类型为该生物所拥有的能量抗力或能量免疫类型。最多可以叠加为同种类抗力30点，不过这些抗力与其他资源得到的抗力不叠加。" },
  { id: "neutralizing", name: "中和", bonus: 1, cl: 5, type: "melee", req: "", desc: "灵光：微弱变化系。这项附魔只能附加在近战武器上。中和武器伸进至多1加仑的非魔法腐蚀性液体中，可以将其全部中和为无害的水。使用中和武器可以对土系亚种生物造成额外1d6点伤害。对基于酸或土的能力的豁免中，持用者可以得到+2表现加值，该武器本身免疫酸伤害。" },
  { id: "ominous", name: "不祥", bonus: 1, cl: 5, type: "melee", req: "", desc: "灵光：微弱塑能系。这项附魔只能附加在近战武器上。持用者将不祥武器的增强加值添加到他的威吓检定上。当使用不祥武器成功造成一次重击时，目标将会战栗1分钟（通过DC13意志豁免无效）。" },
  { id: "planar", name: "位面", bonus: 1, cl: 9, type: "both", req: "", desc: "灵光：中等咒法系。位面武器用来对抗所有异次元的存在，用来在进行物理伤害时穿透他们的伤害减免。当使用位面武器伤害异界生物时，无视它们5点DR。" },
  { id: "quenching", name: "冷却", bonus: 1, cl: 5, type: "melee", req: "", desc: "灵光：微弱变化系。这项附魔只能附加在近战武器上。冷却武器在插入中型或更小的非魔法火焰中时将会迅速熄灭它。当用冷却武器对付火系亚种生物时，它造成额外1d6点伤害。持用者在对抗基于火的能力时豁免得到+2表现加值，该武器本身免疫火焰伤害。" },
  { id: "reliable", name: "可靠", bonus: 1, cl: 8, type: "ranged", req: "firearm", desc: "灵光：中等变化系。这项附魔只能附加在单手火器或双手火器上。这个附魔降低受影响火器的不发火值1点（最低0）。这一降低对所有增加不发火值的情况仍然有效。" },
  { id: "returning", name: "回力", bonus: 1, cl: 7, type: "ranged", req: "thrown", desc: "灵光：中等变化系。这项附魔只能附加在可以用来投掷的武器上。回力武器可以自动回到投掷者手上。回力武器被投出后，会在持用者下一次行动开始前回到他手中。抓住飞回的回力武器是一个自由动作。" },
  { id: "seaborne", name: "海灵", bonus: 1, cl: 7, type: "melee", req: "", desc: "灵光：中等变化系。这项附魔只能附加在近战武器上。持握该武器时，持用者的游泳技能检定得到加值，其数值为武器增强加值数值的双倍。额外地，持用者在水中使用该武器不受到水下攻击和伤害减值。" },
  { id: "seeking", name: "寻踪", bonus: 1, cl: 12, type: "ranged", req: "", desc: "灵光：强烈预言系。这项附魔只能附加在远程武器上。用该武器攻击目标时，没有失手机率，比如目标有隐蔽时。持用者仍然需要瞄准目标所在的位置。" },
  { id: "shock", name: "电击", bonus: 1, cl: 8, type: "both", req: "", desc: "灵光：中等塑能系。一旦被下令启动，电击武器便被电流包覆。电流不会伤害持用者。攻击成功时，电击武器造成额外1d6点电击伤害。" },
  { id: "spell_storing", name: "储法", bonus: 1, cl: 12, type: "both", req: "", desc: "灵光：强烈塑能系和其它。储法武器允许施法者在武器中储存一个针对单体目标且至多为3环的法术。武器一旦伤害到目标生物，持用者便能立刻以一个自由动作施展武器上的法术于目标生物身上。" },
  { id: "thawing", name: "融化", bonus: 1, cl: 5, type: "melee", req: "", desc: "灵光：微弱变化系。这种能力只能附加在近战武器上。将融化武器插进一个中型或更小体型的非魔法冰块中，该冰块会迅速融化。使用融化武器对抗寒系亚种时，可以造成额外1d6点伤害。持用者对抗基于冷的能力时豁免得到+2表现加值，该武器本身免疫寒冷伤害。" },
  { id: "throwing", name: "投掷", bonus: 1, cl: 5, type: "melee", req: "", desc: "灵光：微弱变化系。这项附魔只能附加在近战武器上。擅长此种类武器的持用者可以投掷此武器，射程增量为10尺。" },
  { id: "thundering", name: "雷鸣", bonus: 1, cl: 5, type: "both", req: "", desc: "灵光：微弱死灵系。重击时，雷鸣武器能造成额外的1d8音波伤害。弓、弩和投石索自动将音波能量灌注在其发射的弹药中。遭受雷鸣武器重击的对象须进行DC14的强韧豁免检定，失败则永久变聋。" },
  { id: "valiant", name: "勇气", bonus: 1, cl: 5, type: "melee", req: "", desc: "灵光：微弱预言系。这项附魔只能附加在近战武器上。当骑士持有该武器时挑战一个敌人，该武器在命中该敌人时造成额外1d6点伤害。该骑士对该挑战目标的卸武和破武战技的CMB+2，对抗该目标的卸武和破武战技的CMD+4。" },
  { id: "vicious", name: "反噬", bonus: 1, cl: 9, type: "melee", req: "", desc: "灵光：中等死灵系。这项附魔只能附加在近战武器上。反噬武器击中目标时会制造出一道能让持用者和目标产生共鸣的分裂性能量。能量对目标造成额外2d6点伤害，同时对持用者造成1d6点伤害。" },
  { id: "agile", name: "灵巧", bonus: 1, cl: 7, type: "melee", req: "finesseable", desc: "灵光：中等变化系。一个拥有武器娴熟专长的角色可以用他的敏捷加值替代力量加值加在灵巧武器的伤害投上。这个特殊能力只能附在可以用武器娴熟的近战武器上。" },
  { id: "answering", name: "回应", bonus: 1, cl: 7, type: "melee", req: "", desc: "该能力只能附魔在近战武器上。计算使用适时格挡反击（Opportune Parry and Riposte）炫技，武器的增强加值增加4点（最高为+5）。" },
  { id: "blood_hunting", name: "血狩", bonus: 1, cl: 8, type: "both", req: "", desc: "灵光：中等咒法系。在对抗选定的敌人时，武器的增强加值比实际加值要高2点。它还会对此类敌人造成额外2d6点伤害。在与破敌或猎魄之类的能力结合使用时，这些能力所赋予的增强加值的提升并不会叠加，但是在第一个能力之上，每个特殊能力会使得额外伤害进一步提高1d6点。" },
  { id: "bloodsong", name: "血歌", bonus: 1, cl: 6, type: "melee", req: "slashing_piercing", desc: "灵光：中等变化系。这个特殊能力只能应用在挥砍或穿刺近战武器上。当持用者获得来自战怒之歌表演的好处时，这件武器便会获得锐锋武器特殊能力。若持用者在处于战怒之歌的效果影响下的时候造成了重击的话，则会获得1d10点临时生命值。" },
  { id: "brawling", name: "斗殴", bonus: 1, cl: 7, type: "melee", req: "bludgeoning", desc: "灵光：中等附魔系。这个特殊能力只能应用在黄铜指虎、拳套、闷棍或轻型钝击武器上。这件武器持用者的战技检定会获得增强加值，数值与武器的增强加值相等。" },
  { id: "confounding", name: "花招", bonus: 1, cl: 5, type: "melee", req: "", desc: "灵光：微弱变化系。当持用者使用花招武器造成重击时，她能够花费1点时髦值，来使用直觉动作尝试对目标进行卸武、移位、破武或摔绊战技，战技检定获得等同于花招武器增强加值数的增强加值。这些战技不会引起借机攻击。" },
  { id: "distracting", name: "分神", bonus: 1, cl: 5, type: "both", req: "", desc: "灵光：微弱附魔系。每当一名生物被分神武器命中后，假设必须进行成功的专注检定才能完成一个法术、或者使用特殊能力或物品的话，这些检定的DC会增加5点。分神效果持续1分钟。" },
  { id: "fortuitous", name: "破则", bonus: 1, cl: 8, type: "melee", req: "", desc: "灵光：中等变化系。该特殊能力仅能被附在近战武器上。每轮1次，当破则武器的持用者使用一次借机攻击命中时，他能用这把武器对该名敌人进行第二次借机攻击，不过该次攻击会受到-5减值。" },
  { id: "inspired", name: "启发", bonus: 1, cl: 7, type: "both", req: "", desc: "灵光：中等附魔系。该特殊能力仅能被附在简易武器、手臂、细剑、短弓、短剑和杖剑上。在调查员的手中，武器的持用者仅需要花费1点灵感点来强化该武器的攻击检定。若持用者已经具有战斗灵感调查员天赋的话，他还能将灵感检定结果的两倍加到武器的伤害检定上。" },
  { id: "sacred", name: "祀神", bonus: 1, cl: 16, type: "melee", req: "", desc: "灵光：强烈变化系。祀神武器充盈着神圣能量，它被视为一枚圣徽。此外，若持用者具有祝福职业能力的话，每当他引导能量时，能够在引导能量的区域内选择一个盟友或盟友的武器，并花费一次祝福的使用次数来将一个次级祝福的好处赋予到那个生物或武器上。" },
  { id: "spirit_hunting", name: "猎魄", bonus: 1, cl: 8, type: "both", req: "", desc: "灵光：中等咒法系。在对抗选定的敌人时，武器的增强加值比实际加值要高2点。它还会对此类敌人造成额外2d6点伤害。在与破敌或血狩之类的能力结合使用时，这些能力所赋予的增强加值的提升并不会叠加，但是在第一个能力之上，每个特殊能力会使得额外伤害进一步提高1d6点。" },
  { id: "fate_stealing", name: "盗运", bonus: 1, cl: 5, type: "melee", req: "", desc: "灵光：微弱死灵系。该特殊能力仅能被附在近战武器上。当盗运武器命中的生物具有勇毅或派头职业能力时，持用者能够以迅捷动作盗取1点勇毅值或时髦值。当持用者盗走勇毅值或时髦值之后，她便会恢复1点勇毅值或时髦值。" },
  { id: "flamboyant", name: "华丽", bonus: 1, cl: 8, type: "melee", req: "finesseable_piercing", desc: "灵光：中等变化系。该特殊能力仅能被附在单手或轻型穿刺近战武器上。华丽武器上存有1点时髦值，它会在每日起始时恢复。无论华丽武器的使用者具有什么炫技，她总是可以从华丽武器中花费1点时髦值来重掷一次由于自然掷出1点而失手的攻击。" },

  { id: "advancing", name: "推进", bonus: 2, cl: 5, type: "melee", req: "", desc: "灵光：微弱变化系。这项附魔只能附加在近战武器上。每轮1次，当持用者用该武器命中一个生物时，他可以在伤害结算完后、回合结束之前以迅捷动作进行一次五尺快步。这种移动并不影响他的其他移动方式，不占用本轮中的正常五尺快步计数。进行该特殊移动后，直到下一回合开始所有攻击-2。" },
  { id: "anarchic", name: "混沌", bonus: 2, cl: 7, type: "both", req: "", desc: "灵光：中等塑能系。混沌武器属于混乱阵营，灌注有混乱的力量，并因此能够穿透相应的伤害减免。攻击秩序阵营的生物时，武器能造成2d6点额外伤害。任何企图使用此武器的秩序阵营生物会遭受1个负向等级。" },
  { id: "anchoring", name: "定身", bonus: 2, cl: 10, type: "both", req: "", desc: "灵光：中等变化系。这种能力只能附加在近战武器或投掷武器上。以一个迅捷动作，该武器可以定住空间内的一个角落，如同不动权杖一般运作。当持用者用近战定身武器命中一个生物时，武器吸附住该生物，阻止它离开武器的表面。" },
  { id: "axiomatic", name: "公理", bonus: 2, cl: 7, type: "both", req: "", desc: "灵光：中等塑能系。公理武器属于秩序阵营，灌注有秩序的力量，并因此能够穿透相应的伤害减免。攻击混乱阵营的生物时，武器能造成2d6点额外伤害。任何企图使用此武器的混乱阵营生物会遭受1个负向等级。" },
  { id: "corrosive_burst", name: "酸爆", bonus: 2, cl: 12, type: "both", req: "", desc: "灵光：中等塑能系。酸爆武器的作用方式如同酸蚀武器，除此之外还能在成功的重击后造成更多的伤害。在成功重击后还能再造成1d10点强酸伤害。如果武器的重击倍数为×3，该额外伤害为2d10；如果重击倍数为×4，则额外伤害为3d10。" },
  { id: "defiant", name: "勇猛", bonus: 2, cl: 10, type: "melee", req: "", desc: "灵光：强烈防护系。这项附魔只能附加在近战武器上。当持用者在进行稳定伤势检定，以及终结疾病、毒药、人类定身术之类的持续性效果时，可以将勇猛武器的增强加值添加到豁免上。" },
  { id: "designating_lesser", name: "次等标记", bonus: 2, cl: 7, type: "ranged", req: "", desc: "灵光：中等附魔系。这项附魔只能附加在远程武器或者弹药上。每次该远程武器或弹药命中一个生物时，奥法力量标记了那个敌人。1轮内，所有同伴对该生物的近战攻击和伤害检定得到+2士气加值。" },
  { id: "dispelling_burst", name: "灭法", bonus: 2, cl: 12, type: "both", req: "", desc: "灵光：强烈防护系。灭法武器如同破法武器一般，不过灭法武器可以存储“解除魔法”或“高等解除魔法”。额外的，这个法术可以在用该武器成功造成重击时，以一个自由动作启动。" },
  { id: "disruption", name: "瓦解", bonus: 2, cl: 14, type: "melee", req: "bludgeoning", desc: "灵光：强烈咒法系。瓦解武器是所有不死生物的克星。任何在战斗中被击中的不死生物必须进行一次DC14的意志豁免检定，失败则被摧毁。只有钝击武器才能具有此能力。" },
  { id: "flaming_burst", name: "焰爆", bonus: 2, cl: 12, type: "both", req: "", desc: "灵光：强烈塑能系。焰爆武器的作用方式和炽焰武器一样，除此之外在造成重击时还会爆出一团不会伤害持用者的火焰。重击时还会再造成1d10点火焰伤害。如果武器的重击倍数为×3，则再增加2d10点火焰伤害；如果是×4，则再增加3d10点。" },
  { id: "furyborn", name: "渐狂", bonus: 2, cl: 7, type: "melee", req: "", desc: "灵光：中等附魔系。这项附魔只能附加在近战武器上。每次持用者用该武器伤害一个目标后，武器的增强加值得到+1加值—该加值只在攻击该目标时起作用（武器最大可有+5增强加值）。" },
  { id: "holy", name: "神圣", bonus: 2, cl: 7, type: "both", req: "", desc: "灵光：中等塑能系。神圣武器属于善良阵营，充满了强大的神圣之力，并因此能够穿透相应的伤害减免。攻击邪恶阵营的生物时，武器能造成2d6点额外伤害。任何企图使用此武器的邪恶阵营生物会遭受1个负向等级。" },
  { id: "icy_burst", name: "冰爆", bonus: 2, cl: 10, type: "both", req: "", desc: "灵光：中等塑能系。冰爆武器的作用方式和冻寒武器一样，除此之外在造成重击时还会爆出一团不会伤害持用者的寒霜。重击时还会再造成1d10点寒冷伤害。如果武器的重击倍数为×3，则增加2d10点寒冷伤害；如果是×4，则增加3d10点。" },
  { id: "igniting", name: "引燃", bonus: 2, cl: 12, type: "both", req: "", desc: "灵光：强烈塑能系。引燃武器类似炽焰武器，并能在进行成功的重击后引燃该目标。该目标不能通过豁免来防止着火，不过它可以在每回合开始做一次豁免检定来扑灭火焰。" },
  { id: "impact", name: "冲击", bonus: 2, cl: 9, type: "melee", req: "non_light", desc: "灵光：中等变化系。这项附魔只能附加在非轻型近战武器上。冲击武器攻击时，制造有效的动力冲击用于伤害敌方，在造成伤害时该武器视作大一个体型来计算。" },
  { id: "invigorating", name: "兴奋", bonus: 2, cl: 5, type: "melee", req: "", desc: "灵光：微弱附魔系。这项附魔只能附加在近战武器上。在使用该武器打倒一个敌对生物后，如果持用者处于疲乏下，他会不再疲乏；如果持用者处于力竭下，他将变为疲乏代替力竭。" },
  { id: "ki_intensifying", name: "强气", bonus: 2, cl: 12, type: "melee", req: "", desc: "灵光：强烈变化系。这种武器引导并增强持用者的气，允许持用者通过该武器使出气来攻击，如同徒手使用气一般。这些能力的DC增加一半该武器的增强加值（最小+1）。" },
  { id: "lifesurge", name: "命潮", bonus: 2, cl: 8, type: "melee", req: "", desc: "灵光：中等咒法系。这项附魔只能附加在近战武器上。当持用者在对抗属性伤害、属性吸取、不死生物的能量吸取进行豁免检定时，可以将命潮武器的增强加值添加到这次豁免上。" },
  { id: "negating", name: "否决", bonus: 2, cl: 5, type: "melee", req: "", desc: "灵光：中等防护系。否决武器在伤害生物时减少它的伤害减免。当使用否决武器伤害一个敌人时，若该敌人具有特定阵营或魔法的伤害减免时，可以将该减免的数值减少5，持续1轮。" },
  { id: "phase_locking", name: "闭锁", bonus: 2, cl: 7, type: "both", req: "", desc: "灵光：中等防护系。闭锁武器干涉次元旅行。被闭锁武器伤害的生物如同受到‘次元锚’法术影响1轮。" },
  { id: "shocking_burst", name: "电爆", bonus: 2, cl: 10, type: "both", req: "", desc: "灵光：中等塑能系。电爆武器的作用方式和电击武器一样，除此之外在造成重击时还会爆发出不会伤害持用者的强大电流。重击时还会再造成1d10点电击伤害。如果武器的重击倍率为×3，则再增加2d10点电击伤害；如果是×4，则再增加3d10点。" },
  { id: "stalking", name: "围猎", bonus: 2, cl: 10, type: "both", req: "", desc: "灵光：中等预言系。围猎武器的持用者研究一个目标时间越长，他的下一次攻击效果越好。以一个标准动作，围猎武器的持用者可以专注于研究一个60尺内的目标。当持用者攻击该被研究的目标时，成功攻击能够额外造成伤害，每研究1轮，额外伤害多1d6。" },
  { id: "unholy", name: "邪恶", bonus: 2, cl: 7, type: "both", req: "", desc: "灵光：中等塑能系。邪恶武器属于邪恶阵营，充满了强大的邪恶之力，并因此能够穿透相应的伤害减免。攻击善良阵营的生物时，武器能造成2d6点额外伤害。任何企图使用此武器的善良阵营生物会遭受一个负向等级。" },
  { id: "wounding", name: "血光", bonus: 2, cl: 10, type: "melee", req: "", desc: "灵光：中等塑能系。这项附魔只能附加在近战武器上。血光武器在命中时可以额外造成1点出血伤害。血光武器重复击中可以使流血伤害叠加。出血的生物在该生物的回合开始时受到出血伤害。" },
  { id: "endless_ammunition", name: "无尽", bonus: 2, cl: 8, type: "ranged", req: "bow_crossbow", desc: "灵光：中等咒法系。只有弓和弩才能附加无尽能力——火器和其他弹射武器都不能。每当该武器拉开时，一根非魔法箭矢就会凭空出现并就位。因此持用者无需再从箭匣里取出弹药用以装填。" },
  { id: "glorious", name: "荣耀", bonus: 2, cl: 5, type: "melee", req: "", desc: "灵光：中等塑能系。荣耀武器在拔出鞘时，会发出耀眼的光芒，如同‘昼明术’一般。被该武器击中的目标会目眩到武器持用者的下一回合开始。当使用荣耀武器成功造成重击时，目标将会目盲到武器持用者的下一回合开始（通过DC14的意志豁免无效）。" },
  { id: "distracting_greater", name: "高等分神", bonus: 2, cl: 8, type: "both", req: "", desc: "灵光：中等附魔系。具有此种特殊能力的武器所击中的敌人几乎无法控制自身的魔力。每当一名生物被高等分神武器命中后，假设必须进行成功的专注检定才能完成一个法术、或者使用特殊能力或物品的话，这些检定的DC会增加10点。" },

  { id: "nullifying", name: "抵消", bonus: 3, cl: 12, type: "melee", req: "", desc: "灵光：强烈防护系。这项附魔只能附加在近战武器上。当使用抵消武器对拥有法术抗力的敌人造成伤害时，它可以短时间内消除一些该敌人的SR。每次使用该武器命中拥有SR的敌人，那么该敌人的SR会减少1，持续1分钟。" },
  { id: "speed", name: "追击", bonus: 3, cl: 7, type: "both", req: "", desc: "灵光：中等变化系。进行全力攻击时，追击武器的持用者能进行一次额外的攻击。这次攻击的BAB为持用者的最大BAB，再加上其他适合当前情况的修正。此特殊能力的效果不与其他类似效果叠加，例如‘加速术’。" },
  { id: "repositioning", name: "移位", bonus: 3, cl: 10, type: "melee", req: "", desc: "灵光：中等附魔系。这项附魔只能附加在近战武器上。移位武器给予持用者的移位战技+2增强加值。如果持用者使用该武器成功造成一次重击，他能以自由动作尝试一次移位战技。" },
  { id: "spellstealing", name: "窃法", bonus: 3, cl: 13, type: "melee", req: "", desc: "灵光：强烈预言系。这项附魔只能附加在近战武器上。窃法武器允许持用者吸取目标身上的防御性法术并将其转移到自己身上。当持用者对一个目标造成重击威胁时，他可以放弃确认这次重击，取而代之的是，知晓到目标身上所具有的法术或魔法效果。" },
  { id: "exhausting", name: "力竭", bonus: 3, cl: 12, type: "melee", req: "", desc: "灵光：强烈死灵系。该特殊能力仅能被附在近战武器上。力竭武器能够在战斗中给予敌人极度的疲倦感。在重击时，持用者能够选择放弃额外的伤害，来削弱敌人的力量与精力作为替代，使其变得力竭。" },
  { id: "lucky_greater", name: "高等幸运", bonus: 3, cl: 12, type: "ranged", req: "firearm", desc: "灵光：强烈附魔系。这个特殊能力只能添加在单手火器或双手火器上。一件高等幸运火器几乎和幸运火器一样，可是它的勇毅池里有3点勇毅点。一件火器不能同时附加高等幸运和幸运能力。" },
  { id: "reliable_greater", name: "高等可靠", bonus: 3, cl: 12, type: "ranged", req: "firearm", desc: "灵光：强烈附魔系。这项附魔只能附加在单手火器或双手火器上。这个附魔降低受影响火器的不发火值4点（最低0）。一件有高等可靠附魔的火器不能同时有可靠附魔。" },
  { id: "flamboyant_greater", name: "高等华丽", bonus: 3, cl: 5, type: "melee", req: "finesseable_piercing", desc: "灵光：中等变化系。该特殊能力仅能被附在单手或轻型穿刺近战武器上。高等华丽武器与华丽武器几乎完全相同，不过它存有3点时髦值而非1点。同一把武器不能同时具有高等华丽特殊能力与华丽特殊能力。" },

  { id: "brilliant_energy", name: "光能", bonus: 4, cl: 16, type: "both", req: "", desc: "灵光：强烈变化系。光能武器的攻击部位是由光构成的，这不会改变武器的重量。它发出亮度和火把一样的光（半径20尺）。光能武器能穿过无生命的物质。护甲和盾牌加值在对抗光能武器时无效。光能武器无法伤害不死生物、构装生物和普通物体。" },
  { id: "dancing", name: "舞空", bonus: 4, cl: 15, type: "melee", req: "", desc: "灵光：强烈变化系。以一个标准动作启动后，舞空武器能自己进行攻击。它的攻击加值和持用者的一样，能攻击4轮，然后就掉在地上。舞空时，武器不能进行借机攻击，并且持用者视作没有装备着这件武器。" },
  { id: "designating_greater", name: "高等标记", bonus: 4, cl: 12, type: "ranged", req: "", desc: "灵光：中等附魔系。这项附魔只能附加在远程武器或者弹药上。每次该远程武器或弹药命中一个生物时，奥法力量标记了那个敌人。1轮内，所有同伴对该生物的近战攻击得到+4士气加值，近战伤害得到+6士气加值。" },
  { id: "nimble_shot", name: "巧射", bonus: 4, cl: 11, type: "ranged", req: "", desc: "灵光：中等防护系。这项附魔只能附加在远程武器上。使用巧射武器攻击时不会引发借机攻击。" },
  { id: "second_chance", name: "二重", bonus: 4, cl: 11, type: "ranged", req: "bow", desc: "灵光：中等防护系。这项附魔只能附加在弓类武器上。每轮一次，当用该武器的一次攻击失手时，能以自由动作使得飞出去的箭矢转向，然后重掷该次攻击。" },

  { id: "vorpal", name: "斩首", bonus: 5, cl: 18, type: "melee", req: "slashing", desc: "灵光：强烈死灵系和变化系。这种强大而可怕的能力使得武器能砍下敌人的头颅。攻击检定掷出天然20并且重击成功的情况下，武器会砍下对手的头。斩首武器必须是挥砍类型的武器。" },
  { id: "flying", name: "飞空", bonus: 5, cl: 16, type: "melee", req: "", desc: "灵光：强烈变化系。该特殊能力仅能被附在近战武器上。飞空武器就如同舞空武器一般，不过当它舞空时，可以指定攻击至多30尺远的敌人。此外，无论何时，最后一个拔出武器的持用者能够以迅捷动作将它召回。" },

  { id: "adaptive", name: "适应", bonus: 0, price: 1000, cl: 1, type: "ranged", req: "composite_bow", desc: "灵光：微弱变化系。这项附魔只能附加在复合弓上。适应复合弓将自动适应持用者的力量，作为一个适合持用者力量加值的复合弓来使用。" },
  { id: "dry_load", name: "干填", bonus: 0, price: 1500, cl: 3, type: "ranged", req: "ammo", desc: "灵光：微弱防护系。这种武器特殊能力只能附加在炼金子弹或金属火器子弹上。干填子弹能够在水下或者任何无氧气的环境下开火。上述价格为附魔50发子弹的总价。" },
  { id: "phantom_ammunition", name: "虚弹", bonus: 0, price: 2000, cl: 7, type: "ranged", req: "ammo", desc: "灵光：中等变化系。该特殊能力仅能被附在弹药上。具有虚弹武器特殊能力的弹药会在发射1轮后消失。此外，若投射物正确命中，伤口会在弹药消失后愈合。此处列出的是给50个弹药附上虚弹的价格。" },
  { id: "prehensile", name: "卷缚", bonus: 0, price: 2500, cl: 7, type: "melee", req: "whip", desc: "灵光：中等附魔系。该特殊能力仅能被附在长鞭上。持用者能够以迅捷动作将卷缚长鞭附着在物体上，就如同爪钩一般。之后可以利用鞭子爬上平台或者摇摆穿过房间或其他任何开放区域。" },
  { id: "impervious", name: "坚固", bonus: 0, price: 3000, cl: 7, type: "both", req: "", desc: "灵光：中等变化系。坚固武器十分经久耐用。即便是魔法和超自然手段也无法使金属的坚固武器生锈，或使木制的坚固武器腐烂和变形。坚固武器从每一点增强加值上得到双倍的硬度和HP。" },
  { id: "exclusionary", name: "排斥", bonus: 0, price: 3750, cl: 1, type: "both", req: "", desc: "灵光：微弱死灵系。当持用者使用排斥武器的对一个生物造成伤害时，她能够选择在接下来的1分钟里，自己的任何引导能量能力是否影响该名生物。" },
  { id: "glamered", name: "幻化", bonus: 0, price: 4000, cl: 10, type: "both", req: "", desc: "灵光：中等幻术系。幻化武器可以用口令启动，改变它的形状和表面，完全将其变成一个相似大小的其他物品。武器在伪装时保留他的所有特性，不过它将不再散发灵光。" },
  { id: "sneaky", name: "鬼崇", bonus: 0, price: 5000, cl: 7, type: "melee", req: "", desc: "灵光：中等死灵系。该特殊能力仅能被附在近战武器上。每日1次以自由动作，鬼票武器的持用者能够指定自己近战触及内的单个敌人为猎物。若持用者具有偷袭职业能力，即便持用者没有夹击对方、目标的AC也没有失去敏捷加值，他也能够将偷袭伤害加到下次对猎物做出的攻击上。" },
  { id: "transformative", name: "变形", bonus: 0, price: 10000, cl: 10, type: "melee", req: "", desc: "灵光：中等变化系。这项附魔只能附加在近战武器上。在持用者的命令下变形武器可以改变它的形态，变成另一把相同体型和硬度的近战武器。武器保留它所有的能力——增强加值、武器特殊能力，除了那些因形状不对而丧失的能力。" },
  { id: "dueling", name: "决斗", bonus: 0, price: 14000, cl: 5, type: "melee", req: "finesseable", desc: "灵光：微弱变化系。这项附魔只能附加在近战武器上。决斗武器给予持用者的先攻检定+4增强加值，不过进行先攻检定时该武器必须在手上。持用者的卸武战技和虚招检定+2，对抗卸武的CMD+2，他人对你使用虚招的DC+2。" }
];

export const ARMOR_ABILITIES = [
  { id: "balanced", name: "平衡", bonus: 1, price: 0, cl: 5, type: "armor", req: "light_medium", desc: "灵光：微弱变化系。当它的穿戴者撞到地上时将会反向推他一把。穿戴者对抗闯越和摔绊的CMD+4，保持平衡的特技检定+4。穿戴者主动卧倒是一个移动动作而不是自由动作。平衡能力只能附加在轻甲和中甲上，无法附加到重甲和盾牌上。" },
  { id: "fortification_light", name: "次等护命", bonus: 1, price: 0, cl: 13, type: "both", req: "", desc: "灵光：强烈防护系。这种能力防具能在穿戴者生死攸关的时刻提供有效的魔法防护。当使用者遭受重击或偷袭时，该能力有一定机率把重击或偷袭转化为普通攻击。次等护命有25%机率。" },
  { id: "bitter", name: "苦涩", bonus: 1, price: 0, cl: 5, type: "armor", req: "", desc: "灵光：微弱变化系。这件防具在每次被什么东西咬或吞噬时散发出异常肮脏和苦涩的味道。任何进行啮咬攻击（或者其它用嘴进行的攻击）成功擒抱穿戴者的生物必须通过DC14的强韧检定，不然会立刻吐出来并结束擒抱。如果穿戴者被活吞，吞噬生物必须在受害者存活时，自己每轮开始必须进行DC14的强韧检定，失败则会恶心1轮。吐出受害者是一个标准动作。这是一种毒素效果。" },
  { id: "grinding", name: "尖刺", bonus: 1, price: 0, cl: 5, type: "armor", req: "", desc: "灵光：微弱变化系。当穿戴者被擒抱或者被纠缠时，尖刺防具会使他浑身覆盖上锯齿状的毛刺和锋利的尖刺。任何成功对穿戴者使用擒抱战技的家伙会受到等同于防具增强加值的伤害（每次成功的擒抱检定受到1次），那些尖刺和锯齿会深深刺入擒抱者的身体里。当在穿戴者的回合里，这个能力造出的尖刺视作甲刺。" },
  { id: "bolstering", name: "激励", bonus: 1, price: 0, cl: 5, type: "both", req: "", desc: "灵光：微弱附魔系。每当激励防具的穿戴者成功通过近战或者远程击中一名敌人时，他在对抗这名敌人的任何能力时豁免得到+2表现加值，持续到穿戴者下一回合开始。这个能力可以附加到中甲、重甲、轻盾、重盾和塔盾上，无法附加在轻甲和小圆盾上。" },
  { id: "mirrored", name: "镜映", bonus: 1, price: 0, cl: 8, type: "both", req: "", desc: "灵光：中等防护系。将表面抛光如同镜面的盾牌或护甲闪闪发光，可以作为普通的镜子。此外，与具有“凝视攻击”的生物作战时，它将会有大作用。如果穿戴者选择避开凝视的眼睛，他可以攻击时投掷两次失手率并选择较好的结果。穿戴者可以对隐蔽目标造成偷袭和精准伤害。镜映防具能将它的增强加值添加到穿戴者对抗射线攻击的接触AC上。这种能力只能附加到金属护甲或金属盾牌上。" },
  { id: "champion", name: "勇士", bonus: 1, price: 0, cl: 5, type: "both", req: "", desc: "灵光：微弱防护系。这种防具特殊能力只对善良生物有效，并且该生物必须有挑战类能力（如骑士或者拥有【制裁邪恶】能力的圣武士、半天界生物、天界模版生物）。穿戴者在面对他们选择的对手时AC得到+2神圣加值。" },
  { id: "dastard", name: "卑劣", bonus: 1, price: 0, cl: 5, type: "both", req: "", desc: "灵光：微弱防护系。这种防具特殊能力只对邪恶生物有效，并且该生物必须有挑战类能力（如骑士或者拥有【制裁善良】能力的反圣武士、半炼狱生物、炼狱模板生物）。穿戴者在面对他们选择的对手时AC得到+2亵渎加值。" },
  { id: "stanching", name: "止血", bonus: 1, price: 0, cl: 7, type: "armor", req: "", desc: "灵光：中等变化系。止血防具可以组织穿戴者的伤口继续流血，它会自动聚合伤口并止血，即是是严重的伤口也不例外。穿戴者的任何从出血效果里受到的HP伤害、属性伤害、属性吸收都会减少等同于防具增强加值的数值。同时可以将防具的增强加值添加到稳定伤势的体质检定上。" },
  { id: "deathless", name: "拒亡", bonus: 1, price: 0, cl: 7, type: "armor", req: "", desc: "灵光：中等防护系。这件防具保护它的穿戴者免收有害的负能量或者正能量的影响，包括【引导能量】。它吸收每次正常受到伤害时的前10点正能量伤害或者负能量伤害。同时它还有25%机率忽视负向等级效果。拒亡防具并不会阻止任何治疗形式的正负能量、不造成伤害的正负能量影响和消除负向等级的能力。拒亡能力可以附加在任意护甲上，但是不能附加在盾牌上。" },
  { id: "warding", name: "戒备", bonus: 1, price: 0, cl: 12, type: "both", req: "", desc: "灵光：强烈防护系。每天1次，直觉动作，穿戴者可以结束自己身上所有的挑战、审判、制裁效果。这并不会阻止对手继续将你选为这些能力的目标。以一个迅捷动作，穿戴者可以消耗自己的一次挑战、审判、制裁能力，来刷新该防具能力的使用次数（新的使用次数依旧需要直觉动作启动）。" },
  { id: "defiant_armor", name: "挑战", bonus: 1, price: 0, cl: 8, type: "both", req: "", desc: "灵光：中等咒法系。具有该能力的护甲和盾牌特别擅长对付某种类的敌人，类似于（破敌）武器特别擅长与对付某种类敌人一样。当面对该特定种类敌人时，该防具的AC得到额外+2增强加值以及得到只针对该类生物的DR2/-。这额外加值只和防具本身的增强加值叠加，而不是临时加值。" },
  { id: "vouchsafing", name: "自救", bonus: 1, price: 0, cl: 9, type: "both", req: "", desc: "灵光：中等防护系。自救护甲会在穿戴者陷入昏迷、反胃、震慑或被压制时赋予其DR5/一。这些DR与穿戴者已经具有的任何其他DR相叠加。若穿戴者能够以某种方式在昏迷、反胃、或震慑时进行标准动作，或者能够在被压制时进行攻击，那么护甲便会不再赋予其DR。" },
  { id: "calming", name: "平和", bonus: 1, price: 0, cl: 5, type: "armor", req: "", desc: "灵光：微弱附魔系。平和护甲会被涂上或染上柔和的颜色，通常为蓝色。以迅捷动作，穿戴者能够制造出围绕自身的5尺灵光，这灵光能够让任何威胁到她的激动的敌人心境平和下来。正处于狂暴或正受到情绪效果影响的生物必须进行DC15的意志豁免，失败的话只要灵光仍持续存在，这些效果就会被压制（但是不是解除）下去。灵光每日最多使用10轮，不过这些轮数不必连续。终止灵光是迅捷动作。" },
  { id: "benevolent_armor", name: "仁慈", bonus: 1, price: 0, cl: 5, type: "both", req: "", desc: "灵光：微弱附魔系。这种防具最适合那些关心同伴、喜欢协助和保护同伴的人。当仁慈防具的穿戴者用援助他人动作给予同伴AC加值来对抗下一次攻击时，她可以将仁慈防具的增强加值也添加到同伴的AC上。" },
  { id: "arrow_catching", name: "吸矢", bonus: 1, price: 0, cl: 8, type: "shield", req: "", desc: "灵光：中等防护系。具有这种能力的盾牌能吸引远程武器的攻击。它能使投掷和弹射武器转向，因此在抵御远距离武器的攻击时有+1偏斜加值。此外，任何瞄准盾牌使用者周围5尺内目标的投掷和弹射武器，其攻击会自动由原目标转向盾牌使用者。使用者能以一句指令启动和关闭此特殊能力。" },
  { id: "bashing", name: "猛击", bonus: 1, price: 0, cl: 8, type: "shield", req: "", desc: "灵光：中等变化系。具有这特殊能力的盾牌就是被设计用来盾牌猛击的。一面猛击盾牌造成的伤害视作大2个体型的武器（中型轻盾造成1d6点伤害，中型重盾造成1d8点伤害）。该盾牌猛击时视作+1武器。只有轻盾和重盾可以附加该能力。" },
  { id: "guarding", name: "护卫", bonus: 1, price: 0, cl: 8, type: "shield", req: "", desc: "灵光：中等防护系。护卫盾牌允许佩戴者将部分或全部盾牌的增强加值转移到一名临近生物的AC上（该加值与所有其他加值叠加）。在盾牌的佩戴者回合开始时，并且使用盾牌的任何其他能力之前，她可以选择一名相邻的目标，以一个自由动作选择如何分配盾牌的增强加值，并将这些加值赋予目标。目标的AC加值持续至佩戴者的下一个回合，或者持续到佩戴者与目标之间的距离超过5尺。" },
  { id: "blinding", name: "目盲", bonus: 1, price: 0, cl: 7, type: "shield", req: "", desc: "灵光：中等塑能系。该能力的盾牌需要启动使用，每天2次，发出耀眼的光芒。20尺内的除使用者外的生物必须进行DC14的反射豁免检定，失败则目盲1d4轮。" },
  { id: "clangorous", name: "嘹亮", bonus: 1, price: 0, cl: 7, type: "shield", req: "", desc: "灵光：中等塑能系。具有该特殊能力的盾牌在被击中时能发出震耳欲聋的响声。当使用者被一次攻击击中时，可以用一个直觉动作使盾牌发出巨大的响声，如同一颗爆雷石一般。如果这次攻击造成了重击，则可以激发一次‘音鸣爆’（强韧DC13）来代替。使用者自主决定效果激发的地区，不过必须将攻击者包含在内。使用者不会受到这些能力影响。" },
  { id: "ramming", name: "猛冲", bonus: 1, price: 0, cl: 5, type: "shield", req: "", desc: "灵光：微弱塑能系。猛冲盾牌通常坚固，画有公牛或者公羊图案。当使用者在一次冲锋中用猛冲盾牌进行盾牌猛击，他可以将盾牌的AC增强加值添加到该次猛击的攻击和伤害中。这个加值不和盾牌的其他增强加值叠加。如果该猛击命中，他可以用一个迅捷动作对目标尝试一次冲撞战技，将冲锋所带来的+2奖励和盾牌的增强加值合计并增加到该次冲撞检定中。只有能够进行盾牌猛击的盾牌才可以附加该能力。" },

  { id: "animated", name: "活化", bonus: 2, price: 0, cl: 12, type: "shield", req: "", desc: "灵光：强烈变化系。以一个移动动作，一件活化盾牌被解放自动防卫它的使用者。接下来的4轮，它的使用者保有该盾牌的一切加值，时间到后盾牌将掉落在地。活化时，盾牌提供它所有的盾牌加值和特殊能力，不过它不能自主使用需要动作的能力，比如（猛击）或（目盲）。不过，那些不需要动作的特殊能力会一直作用，比如（辟矢）和（镜反）。活化时，盾牌占据和激活者相同的位置并跟随移动，哪怕这人用法术手段进行了移动。拥有活化盾的角色依然受到相关使用盾牌的惩罚，比如防具检定减值、奥术施法失败率、不熟练减值。如果使用者有一只空闲的手，他能以自由动作抓住活化中的盾并结束活化状态。一旦盾牌恢复正常，至少4轮内无法再次被激活。这个特殊能力不能附加在塔盾上。" },
  { id: "merging", name: "融合", bonus: 2, price: 0, cl: 10, type: "shield", req: "", desc: "灵光：中等变化系。融合盾牌可以选择与一个单手武器或轻型武器融合。穿戴者每轮都可以选择以武器攻击，还是以盾牌防御。融合或者解除融合都需要口令。融合时必须持握在手上，解除融合时盾牌也会出现在手上。当融合时，穿戴者的那只手只能用来以武器攻击或以盾牌防御（而不能施法和持握物品）。融合轻盾的武器攻击-2，融合重盾的武器攻击-4。如果穿戴者用融合盾牌的武器攻击，他将失去盾牌加值，直到他的下一回合开始。已融合盾牌不能用来做盾牌猛击。只有轻盾和重盾可以附加融合能力。" },
  { id: "arrow_deflection", name: "辟矢", bonus: 2, price: 0, cl: 5, type: "shield", req: "", desc: "灵光：微弱防护系。此盾牌的使用者如同具有“拔挡飞箭”专长。当他受到远程攻击时，每轮有1次机会进行DC20的反射豁免检定。如果攻击武器（或弹药）有增强加值，DC增加相应的数值。通过检定则盾牌使武器被偏转。使用者若没有发现此次攻击或处于措手不及状态则不能使用此能力。尝试偏转远程武器不算一个动作。有一些例外的远程武器，如巨人投出的石块和“强酸箭”不能被偏斜。" },
  { id: "spell_resistance_13", name: "抗法 13", bonus: 2, price: 0, cl: 15, type: "both", req: "", desc: "灵光：强烈防护系。这种防具给予穿戴者法术抗力13。" },
  { id: "guarding_greater", name: "高等护卫", bonus: 2, price: 0, cl: 12, type: "shield", req: "", desc: "灵光：强烈防护系。高等护卫的效果如同护卫，除了佩戴者能以一个自由动作，选择任意数量相邻的盟友受到盾牌的加值。所有被选定的盟友受到相同加值。如果被护卫的目标与佩戴者间的距离超过5尺，他受到的效果会结束，但是这不影响其他被影响目标获得的加值。" },
  { id: "jarring", name: "反震", bonus: 2, price: 0, cl: 6, type: "both", req: "", desc: "灵光：中等塑能系。具有该能力的盾牌或者护甲能够对击中其穿戴者的武器产生让人不快的共振。每日至多3次以直觉动作，当穿戴者被武器造成的一次近战攻击命中时，他能够启动护甲或盾牌，通过武器将剧烈的震动回馈给攻击者。攻击者必须进行DC16的强韧豁免，失败则会晕眩1轮。" },
  { id: "spell_dodging", name: "闪咒", bonus: 2, price: 0, cl: 4, type: "armor", req: "", desc: "灵光：微弱防护系。闪咒能够让来自法术和类法术的攻击难以命中其穿戴者，护甲通常会以通过在物理上推拉穿戴者的方式，使其远离即将袭来的魔法攻击。穿戴者在对抗来自法术或类法术能力的攻击（包括接触攻击）以及召唤生物的攻击时，AC获得+4闪避加值。" },

  { id: "fortification_moderate", name: "中等护命", bonus: 3, price: 0, cl: 13, type: "both", req: "", desc: "灵光：强烈防护系。这种能力防具能在穿戴者生死攸关的时刻提供有效的魔法防护。当使用者遭受重击或偷袭时，该能力有50%机率把重击或偷袭转化为普通攻击。" },
  { id: "spell_resistance_15", name: "抗法 15", bonus: 3, price: 0, cl: 15, type: "both", req: "", desc: "灵光：强烈防护系。这种防具给予穿戴者法术抗力15。" },
  { id: "ghost_touch_armor", name: "幽冥", bonus: 3, price: 0, cl: 15, type: "both", req: "", desc: "灵光：强烈变化系。这种防具看上去几乎是透明的。它的增强加值和护甲或盾牌加值都可以在对抗虚体生物时正常作用。任何时刻它都可以被虚体生物拿起、移动和穿戴，并且虚体生物在遭受虚体或实体攻击时，幽冥防具的增强加值可以正常作用，且虚体生物可以正常穿过固态物体。" },
  { id: "titanic", name: "巨大", bonus: 3, price: 0, cl: 7, type: "armor", req: "", desc: "灵光：中等变化系。巨大防具超乎寻常的大，不过它只是看起来如此而已，其内部适合生物正常穿戴，没必要调整。穿戴巨大防具的家伙在使用基于体型的特殊攻击时被视为大1个体型，并在被基于体型的特殊攻击时被视为大1个体型，此类攻击例如“活吞”和“践踏”。每天1次，口令启动，穿戴者可以将自己如同“变巨术”般变大（即使穿戴者不是类人生物），持续1分钟。额外地，每分钟1次，穿戴者能以自由动作激活防具，将防具的增强加值添加到一次单独的力量检定、战技攻击检定或CMD上。因为它的巨大体积，巨大防具要将它的增强加值添加到防具检定减值上。" },
  { id: "invulnerability", name: "坚韧", bonus: 3, price: 0, cl: 18, type: "both", req: "", desc: "灵光：强烈防护系或者强烈塑能系。这种防具给予穿戴者DR5/魔法。如果以“祈愿术”来附魔，则是强烈防护系；以“神迹术”来附魔，则是强烈塑能系。" },
  { id: "wild", name: "野性", bonus: 3, price: 0, cl: 9, type: "both", req: "", desc: "灵光：中等变化系。野性防具通常由强化过的动物皮毛制成。当穿戴此防具时使用【自然变身】能力，防具的护甲或盾牌加值（和任何增强加值）仍然有效。具有此能力的防具包裹着叶子形的装饰。当穿戴者处于变身状态下，防具是不可见的。" },
  { id: "sensing", name: "传感", bonus: 3, price: 0, cl: 14, type: "armor", req: "", desc: "灵光：强烈预言系。传感护甲会在穿戴者目盲时、在穿戴者不具有黑暗视觉或看破黑暗能力的情况下身处完全黑暗时、或者在不具有看破黑暗能力的情况下身处魔法黑暗时补足感官的缺失。当穿戴者受到上述情况之一的影响时，传感护甲会立即赋予其5尺范围的盲视和60尺范围的盲感。一旦穿戴者能够视物，这些额外的感官便会消失。穿戴者无法通过蒙上眼睛来获得这些能力。" },
  { id: "brawling_armor", name: "喧哗", bonus: 3, price: 0, cl: 5, type: "armor", req: "light", desc: "灵光：微弱变化系。喧哗防具使得穿戴者的徒手攻击得到+2攻击和+2伤害加值，包括擒抱战技检定。她的徒手攻击在击破伤害减免时视作魔法武器。这些加值无法作用于天生武器。穿戴者做徒手攻击时依然会引发借机攻击，并且她的徒手攻击也不视为武装攻击。喧哗能力只能附加在轻甲上。" },

  { id: "spell_resistance_17", name: "抗法 17", bonus: 4, price: 0, cl: 15, type: "both", req: "", desc: "灵光：强烈防护系。这种防具给予穿戴者法术抗力17。" },

  { id: "fortification_heavy", name: "高等护命", bonus: 5, price: 0, cl: 13, type: "both", req: "", desc: "灵光：强烈防护系。这种能力防具能在穿戴者生死攸关的时刻提供有效的魔法防护。当使用者遭受重击或偷袭时，该能力有75%机率把重击或偷袭转化为普通攻击。" },
  { id: "spell_resistance_19", name: "抗法 19", bonus: 5, price: 0, cl: 15, type: "both", req: "", desc: "灵光：强烈防护系。这种防具给予穿戴者法术抗力19。" },
  { id: "reflecting", name: "镜反", bonus: 5, price: 0, cl: 14, type: "shield", req: "", desc: "灵光：强烈防护系。这种防具如镜子般光亮，提供了反射能力。每天1次，能使用它反射一个法术，如同‘法术反转一般。" },

  { id: "delving", name: "挖掘", bonus: 0, price: 10000, cl: 5, type: "armor", req: "", desc: "灵光：微弱变化系。这件防具能力给与穿戴者10尺的掘地速度。这允许穿戴者在任何类型的土壤中挖掘隧道通行，比如碎石地，但是实心岩则无法通行。这个能力并不会给与穿戴者在地下呼吸的能力，所以他必须屏住呼吸或者使用其他法术来保证空气和呼吸。此外，穿戴者在面对山体滑坡、崩塌、隧道塌方和其他类似情况时，得到+4豁免加值。" },
  { id: "poison_resistant", name: "抗毒", bonus: 0, price: 2250, cl: 7, type: "both", req: "", desc: "灵光：中等咒法系。这个能力的防具给予穿戴者在对抗毒素时的豁免+3抗力加值。" },
  { id: "putrid", name: "恶臭", bonus: 0, price: 10000, cl: 5, type: "armor", req: "", desc: "灵光：微弱咒法系。恶臭防具会散发出一种令人作呕、胃部翻腾的恶臭。所有10尺以内的生物必须成功通过DC14的强韧检定，失败则恶心5轮。这是一种毒素效果。成功通过豁免检定的家伙在24小时内不再受到相同防具的恶臭效果。具有“恶臭”能力的怪物或者免疫毒素的家伙不受到这个效果影响。穿戴者自身免疫自己的恶臭，对于其他恶臭不免疫。散发恶臭能力可以用口令来开启和关闭，但臭味会在1分钟后完全散发。" },
  { id: "glamered_armor", name: "无相", bonus: 0, price: 2700, cl: 10, type: "armor", req: "", desc: "灵光：中等幻术系。具有此能力的盔甲看起来没什么特别的。命令启动，则盔甲会变成普通衣服的样子。变化后盔甲仍保留原来的属性（包括重量）。只有“真知术”和类似的魔法可以在它伪装时揭示真实。" },
  { id: "harmonizing", name: "协调", bonus: 0, price: 15000, cl: 7, type: "armor", req: "", desc: "灵光：中等幻术系。协调防具的穿戴者每一步都会产生一个交响乐的音符。防具声音与音乐、歌词、他说出的话语一起，创造出了愉快的复合旋律。穿戴者的表演检定得到+5表现加值，反之隐匿检定受到-5惩罚。该防具的穿戴者只有在她没有任何物理行动时才不发声。这个能力同时也放大有害声音，形成更强烈的声波（音波伤害造成额外50%伤害）。" },
  { id: "jousting", name: "骑术", bonus: 0, price: 3750, cl: 5, type: "armor", req: "", desc: "灵光：微弱变化系。这种能力帮助穿戴者骑乘和控制坐骑。穿戴者的骑术检定得到+5表现加值。" },
  { id: "shadow", name: "暗影", bonus: 0, price: 3750, cl: 5, type: "armor", req: "", desc: "灵光：微弱幻术系。这种防具在穿戴者试图隐藏时会变得模糊，并减少发出的声音。穿戴者的隐匿检定得到+5表现加值。防具减值正常计算。" },
  { id: "shadow_improved", name: "强化暗影", bonus: 0, price: 15000, cl: 10, type: "armor", req: "", desc: "灵光：中等幻术系。这种防具在穿戴者试图隐藏时会变得模糊，并减少发出的声音。穿戴者的隐匿检定得到+10表现加值。防具减值正常计算。" },
  { id: "shadow_greater", name: "高等暗影", bonus: 0, price: 33750, cl: 15, type: "armor", req: "", desc: "灵光：强烈幻术系。这种防具在穿戴者试图隐藏时会变得模糊，并减少发出的声音。穿戴者的隐匿检定得到+15表现加值。防具减值正常计算。" },
  { id: "slick", name: "滑溜", bonus: 0, price: 3750, cl: 4, type: "both", req: "", desc: "灵光：微弱咒法系。该防具无论什么时候都像是涂了油一样。穿戴者的逃脱检定得到+5表现加值。防具检定减值正常计算。" },
  { id: "slick_improved", name: "强化滑溜", bonus: 0, price: 15000, cl: 10, type: "both", req: "", desc: "灵光：中等咒法系。该防具无论什么时候都像是涂了油一样。穿戴者的逃脱检定得到+10表现加值。防具检定减值正常计算。" },
  { id: "slick_greater", name: "高等滑溜", bonus: 0, price: 33750, cl: 15, type: "both", req: "", desc: "灵光：强烈咒法系。该防具无论什么时候都像是涂了油一样。穿戴者的逃脱检定得到+15表现加值。防具检定减值正常计算。" },
  { id: "energy_resistance", name: "抗能", bonus: 0, price: 18000, cl: 3, type: "both", req: "", desc: "灵光：微弱防护系。防具上的这种特殊能力能够抵抗某一种能量伤害（强酸、寒冷、闪电、火焰或音波），它的设计式样取决于抵抗的能量类型。抗能防具吸收每次受到所对应能量伤害时的前10点伤害。" },
  { id: "energy_resistance_improved", name: "强化抗能", bonus: 0, price: 42000, cl: 7, type: "both", req: "", desc: "灵光：中等防护系。强化抗能防具吸收前20点伤害。" },
  { id: "energy_resistance_greater", name: "高等抗能", bonus: 0, price: 66000, cl: 11, type: "both", req: "", desc: "灵光：中等防护系。高等抗能防具吸收前30点伤害。" },
  { id: "expeditious", name: "超速", bonus: 0, price: 4000, cl: 5, type: "armor", req: "", desc: "灵光：微弱变化系。每天3次，以一个迅捷动作，超速防具的穿戴者得到+10尺移动速度增强加值，这个加值可以添加到任何移动速度上，持续1轮。所有类型的护甲都可以附加这个能力，但是盾牌不能。" },
  { id: "martyrring", name: "殉难", bonus: 0, price: 18000, cl: 9, type: "armor", req: "", desc: "灵光：中等咒法系。这种能力能将穿戴者的伤化为救助同伴之力。每天1次，以一个直觉动作，当穿戴者被重击时，她可以治疗30尺内的至多9个同伴，如同‘群体治疗轻伤’法术一般（每人1d8+9点治疗）。这个能力不能附加在会消除或者削弱重击的防具上（如无法和〈护命〉能力并存）。" },
  { id: "burdenless", name: "轻松", bonus: 0, price: 4000, cl: 5, type: "both", req: "", desc: "灵光：微弱变化系。轻松护甲能够有效地将穿戴者负载的重量均匀地分摊开，这使得她能够携带更多地东西而不需要承受负重产生的效果。穿戴者在每种载重情况下（轻载、中载和重载）的负荷容量都增加了50%。" },
  { id: "righteous", name: "正义", bonus: 0, price: 27000, cl: 10, type: "armor", req: "", desc: "灵光：中等变化系。该种防具上往往雕刻或者漆印上宗教符号。每天1次，口令启动，穿戴者可以祈求神灵附体，如同法术‘正气如虹’，持续10轮。正义防具始终偏向善良方向（正能量），来决定正气如虹的效果。如果邪恶阵营生物穿上正义防具，它将得到1个负向等级直到它脱下正义防具。这个负向等级在穿戴该防具时不会被任何方法驱散（包括‘复原术’系列）。" },
  { id: "amorphous", name: "液化", bonus: 0, price: 4500, cl: 8, type: "armor", req: "organic", desc: "具有这项特殊能力的护甲会让它的穿戴者在对抗擒抱战技时，逃脱检定和CMD获得+5表现加值。此外，每日1次通过命令，穿戴者（连同她所穿戴的装备）能够呈现出黏性液体的形态，使其能够穿过任何粘稠的泥浆可以流过的空间。在使用该能力时，穿戴者的速度降低10尺，而且只能进行移动动作。穿戴者能够在此形态下保持1分钟，或者直至她花费一个移动动作变回普通形态为止。液化护甲必须由皮革、布匹或者其他柔软的有机材料制成。" },
  { id: "unbound", name: "无拘", bonus: 0, price: 27000, cl: 10, type: "armor", req: "", desc: "灵光：中等变化系。该种防具上往往雕刻或者漆印上混乱宗教符号。每天一次，口令启动，穿戴者如同受到法术‘正气如虹’影响，持续10轮。不过穿戴者得到DR（5/秩序）来代替（DR/邪恶）或者（DR/善良）。如果秩序阵营生物穿上正义防具，它将得到1个负向等级，直到它脱下无拘防具。这个负向等级在穿戴该防具时不会被任何方法驱散（包括‘复原术’系列）。" },
  { id: "restful", name: "宁憩", bonus: 0, price: 4500, cl: 5, type: "armor", req: "", desc: "灵光：微弱死灵系。宁憩护甲使得穿戴者每日所需的连续睡眠或休息时间从8小时降至2小时，而且穿戴者不会由于身穿此件护甲睡觉而疲乏。穿戴者就如同整晚睡在舒适床铺上再醒来一般，如常恢复生命值与属性伤害，和处理疾病、毒素和其他苦难。穿戴宁憩护甲进行额外的休息也不会提供追加的好处，穿戴者每天从护甲的效果中获得好处的次数也不能超过1次。" },
  { id: "unrighteous", name: "邪道", bonus: 0, price: 27000, cl: 10, type: "armor", req: "", desc: "灵光：中等变化系。该种防具上往往雕刻或者漆印上亵渎的符号。每天一次，口令启动，穿戴者可以祈求神灵附体，如同法术‘正气如虹’，持续10轮。邪道防具始终偏向邪恶方向（负能量），来决定‘正气如虹’的效果。如果善良阵营生物穿上邪道防具，它将得到1个负向等级，直到它脱下正义防具。这个负向等级在穿戴该防具时不会被任何方法驱散（包括‘复原术’系列）。" },
  { id: "vigilant", name: "机警", bonus: 0, price: 27000, cl: 10, type: "armor", req: "", desc: "灵光：中等变化系。该种防具上往往雕刻或者漆印上秩序宗教符号。每天一次，口令启动，穿戴者如同受到法术‘正气如虹’影响，持续10轮。不过穿戴者得到DR（5/混乱）来代替（DR/邪恶）或者（DR/善良）。如果混乱阵营生物穿上机警防具，它将得到1个负向等级，直到它脱下机警防具。这个负向等级在穿戴该防具时不会被任何方法驱散（包括‘复原术’系列）。" },
  { id: "cloudburst", name: "豪雨", bonus: 0, price: 5000, cl: 5, type: "armor", req: "", desc: "灵光：微弱防护系与塑能系。这种护甲上通常用暴风之云与闪电簇的雕刻作为装饰。如果一次攻击对佩戴者造成了至少10点闪电伤害，那么护甲会在1轮内明显地充盈着闪电。佩戴者在下一回合可以通过一个不会引发借机攻击的迅捷动作使用‘电爪’，就如同使用类法术能力一般，她能够将前一回会受到的每10点闪电伤害转化为1d6点‘电爪’的闪电伤害。" },
  { id: "creeping", name: "潜行", bonus: 0, price: 5000, cl: 7, type: "armor", req: "", desc: "灵光：中等幻术系和变化系。一套潜行防具能让穿戴者秘密行动。防具的防具检定减值不影响穿戴者的隐匿技能。每天1次，穿戴者说出口令启动，可以将防具的增强加值添加到自己的隐匿检定上，持续1分钟。" },
  { id: "determination", name: "决心", bonus: 0, price: 30000, cl: 10, type: "both", req: "", desc: "灵光：中等咒法系。决心特效的护甲和盾牌将在面对希望渺茫的战斗中提供帮助。每天1次，当穿戴者的HP达到0或者更少，该防具自动激活提供一个“生命之息”法术。" },
  { id: "rallying", name: "增援", bonus: 0, price: 5000, cl: 5, type: "both", req: "", desc: "灵光：微弱防护系。这种防具闪耀着光辉，它如明镜般的表面具备有魔法的能力，给同伴带来信心。穿戴者30尺内的同伴在对抗恐惧的豁免中得到+4士气加值。如果穿戴者拥有对抗恐惧时豁免附加上士气加值的能力（比如圣武士的【勇气灵光】，诗人的【激发勇气】，骑士的【旗帜】等），则该附魔所带来的士气加值增加为+6。" },
  { id: "adhesive", name: "黏着", bonus: 0, price: 7000, cl: 10, type: "armor", req: "", desc: "灵光：中等变化系。一个命令启动，该防具穿戴者的手和脚产生令人难以置信的黏性，他获得20尺攀爬速度。他用徒手攻击或者天生武器施展的卸武、擒抱、移位、盗取、摔绊战技检定得到+2增强加值。这个效果每天可以使用10轮，并且不需要连续，每次使用至少1轮。停止它是一个自由动作。黏着能力无法与防具上任何（滑溜）能力同存。" },
  { id: "spiteful", name: "怨恨", bonus: 0, price: 7000, cl: 7, type: "armor", req: "", desc: "灵光：中等附魔系。该护甲能力仅会在穿戴者具有派头职业能力时才会生效。当位于穿戴者近战触及内的一名敌人做出的一次近战攻击将使得穿戴者的生命值降至0点以下时，穿戴者能够以直觉动作花费1点时髦值。这使得她能够做出单次近战攻击对抗那个使她生命值降低到0或更低的生物。这些动作发生在穿戴者陷入昏迷或死亡之前。" },
  { id: "trackless", name: "无踪", bonus: 0, price: 7500, cl: 5, type: "armor", req: "leather", desc: "灵光：微弱变化系。无踪护甲让穿戴者的脚步更浅，并且对其外观进行了伪装。追踪穿戴者的生存检定会受到-5减值，而且穿戴者在潜行检定中获得+5表现加值。只有皮甲或革甲能够被附上无踪特殊能力。" },
  { id: "etherealness", name: "灵化", bonus: 0, price: 49000, cl: 13, type: "armor", req: "", desc: "灵光：强烈变化系。每天一次，一个命令启动，该防具的穿戴者变化为灵体（如同法术‘幻化灵体’）。任务可以自由决定保持灵体的时间，但他一旦转化为正常状态，当天就不能再转化为灵体。" },
  { id: "hosteling", name: "存贮", bonus: 0, price: 7500, cl: 9, type: "both", req: "", desc: "灵光：中等咒法系。这种能力的防具可以隐藏一个动物来保证它的安全。穿戴者可以说出口令来存贮一只动物，比如动物伙伴、魔宠或者坐骑。被存贮的动物会在防具上化作一个标记，是一个模糊的动物外观或者更抽像的代表。" },
  { id: "undead_controlling", name: "操灵", bonus: 0, price: 49000, cl: 13, type: "both", req: "", desc: "灵光：强烈死灵系。具有此能力的盔甲或盾牌，其穿戴者每天能控制26HD的不死生物，效果等同于‘操控死灵’法术。每天拂晓时，穿戴者失去对仍被控制的不死生物的操纵。" },
  { id: "radiant", name: "光亮", bonus: 0, price: 7500, cl: 6, type: "armor", req: "", desc: "灵光：中等塑能系。光亮防具在穿戴时能如同火把一般发光。这个能力可以用口令来开启和关闭。即便不发光，该防具也会具有明亮的色彩和星辉的光泽。每天1次，穿戴者用口令启动，防具能够如同‘昼明术’一般发出白昼光芒，持续1小时或者用口令关闭。" },
  { id: "wyrmbreath", name: "龙息", bonus: 0, price: 5000, cl: 5, type: "shield", req: "", desc: "灵光：微弱塑能系。这种能力的盾牌上面都会有一个张开的龙嘴图样。该防具制造时选择一种能量类型（强酸、寒冷、闪电或火焰）作为关键能量。穿戴者每受到5点对应能量伤害，盾牌得到1发充能。穿戴者能以口令启动释放1-5发充能，将盾牌当做喷吐武器使用，范围锥形15尺，每点充能造成1d4点伤害（反射DC11减半）。" }
];

